package conformance

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"go.yaml.in/yaml/v3"
)

const yamlHeader = "# Provider conformance ground truth (DELTA-43).\n" +
	"# Generated by `g8s providers conformance --write`; do not hand-edit.\n" +
	"# Base URLs, credentials and host topology are never recorded here.\n"

// LoadMatrix reads and validates a conformance matrix file.
func LoadMatrix(path string) (*Matrix, error) {
	data, err := os.ReadFile(path) // #nosec G304 -- operator-supplied repo path
	if err != nil {
		return nil, fmt.Errorf("read conformance matrix %s: %w", path, err)
	}
	var m Matrix
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse conformance matrix %s: %w", path, err)
	}
	if m.SchemaVersion != SchemaVersion {
		return nil, fmt.Errorf("conformance matrix %s: unsupported schema_version %q (want %q)", path, m.SchemaVersion, SchemaVersion)
	}
	return &m, nil
}

// MarshalMatrix renders the matrix as YAML with the generated-file header.
func MarshalMatrix(m Matrix) ([]byte, error) {
	body, err := yaml.Marshal(m)
	if err != nil {
		return nil, fmt.Errorf("marshal conformance matrix: %w", err)
	}
	return append([]byte(yamlHeader), body...), nil
}

func writeFileAtomic(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("mkdir %s: %w", filepath.Dir(path), err)
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return fmt.Errorf("write %s: %w", tmp, err)
	}
	if err := os.Rename(tmp, path); err != nil {
		return fmt.Errorf("rename %s: %w", tmp, err)
	}
	return nil
}

// WriteMatrix merges update into any existing matrix at path and writes it.
func WriteMatrix(path string, update Matrix) (Matrix, error) {
	var base *Matrix
	if existing, err := LoadMatrix(path); err == nil {
		base = existing
	} else if !errors.Is(err, os.ErrNotExist) {
		return Matrix{}, err
	}
	merged := base.Merge(update)
	data, err := MarshalMatrix(merged)
	if err != nil {
		return Matrix{}, err
	}
	if err := writeFileAtomic(path, data); err != nil {
		return Matrix{}, err
	}
	return merged, nil
}

// WriteDoc renders the markdown matrix to path.
func WriteDoc(path string, m Matrix) error {
	return writeFileAtomic(path, []byte(RenderMarkdown(m)))
}

// RenderMarkdown renders the human-facing provider matrix.
func RenderMarkdown(m Matrix) string {
	var b strings.Builder
	b.WriteString("# Provider Conformance Matrix\n\n")
	b.WriteString("> Generated by `g8s providers conformance --write` from [`.g8s/provider-conformance.yml`](../../.g8s/provider-conformance.yml) ")
	b.WriteString("(schema `" + m.SchemaVersion + "`, generated " + m.GeneratedAt + "). Do not hand-edit; re-run the command instead. ")
	b.WriteString("Contract: [DELTA-43](../../spec/openspec/43-provider-conformance-matrix-spec.md).\n\n")
	b.WriteString("Verdicts: `PASS` and `FAIL` carry runtime or static evidence; `UNSUPPORTED` means the capability is absent; ")
	b.WriteString("`UNVERIFIED` means no evidence was collected (static mode, policy refusal, provider absent, or inconclusive run). ")
	b.WriteString("Required probes are marked with `*`; a required `FAIL` makes `g8s submit` warn (or refuse with `--enforce-conformance`).\n\n")

	providers := append([]ProviderReport(nil), m.Providers...)
	sort.Slice(providers, func(i, j int) bool {
		if providers[i].Class != providers[j].Class {
			return providers[i].Class < providers[j].Class
		}
		return providers[i].Name < providers[j].Name
	})
	for _, class := range []Class{ClassCLIAgent, ClassHTTPLLM} {
		order := CLIProbeOrder
		title := "CLI agents"
		if class == ClassHTTPLLM {
			order = HTTPProbeOrder
			title = "HTTP LLM providers"
		}
		var rows []ProviderReport
		for _, p := range providers {
			if p.Class == class {
				rows = append(rows, p)
			}
		}
		if len(rows) == 0 {
			continue
		}
		b.WriteString("## " + title + "\n\n")
		b.WriteString("| Provider | Version | Mode | Policy |")
		for _, id := range order {
			mark := ""
			if IsRequired(class, id) {
				mark = "*"
			}
			b.WriteString(" " + string(id) + mark + " |")
		}
		b.WriteString("\n|---|---|---|---|")
		for range order {
			b.WriteString("---|")
		}
		b.WriteString("\n")
		for _, p := range rows {
			ver := p.Version
			if ver == "" {
				ver = "-"
			}
			fmt.Fprintf(&b, "| `%s` | %s | %s | %s |", p.Name, mdEscape(ver), p.Mode, p.LivePolicy)
			for _, id := range order {
				st := "-"
				if r, ok := p.Probe(id); ok {
					st = string(r.Status)
				}
				b.WriteString(" " + st + " |")
			}
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Probe legend\n\n| ID | Name |\n|---|---|\n")
	ids := make([]string, 0, len(probeNames))
	for id := range probeNames {
		ids = append(ids, string(id))
	}
	sort.Strings(ids)
	for _, id := range ids {
		fmt.Fprintf(&b, "| %s | `%s` |\n", id, probeNames[ProbeID(id)])
	}
	b.WriteString("\n## Evidence\n\n")
	for _, p := range providers {
		fmt.Fprintf(&b, "### `%s` (%s)\n\n", p.Name, p.Class)
		if p.Model != "" {
			fmt.Fprintf(&b, "Model probed: `%s`. ", p.Model)
		}
		if len(p.FlagsAdvertised) > 0 {
			fmt.Fprintf(&b, "Flags advertised: `%s`.", strings.Join(p.FlagsAdvertised, "`, `"))
		}
		b.WriteString("\n\n| Probe | Status | Mode | Reason | Exit | stdout sha256 | ms | Observed |\n|---|---|---|---|---|---|---|---|\n")
		for _, r := range p.Probes {
			exit, sha, ms, at := "-", "-", "-", "-"
			if r.Evidence != nil {
				exit = fmt.Sprintf("%d", r.Evidence.ExitCode)
				if r.Evidence.HTTPStatus != 0 {
					exit = fmt.Sprintf("%d (http %d)", r.Evidence.ExitCode, r.Evidence.HTTPStatus)
				}
				if len(r.Evidence.StdoutSHA256) >= 12 {
					sha = "`" + r.Evidence.StdoutSHA256[:12] + "`"
				}
				ms = fmt.Sprintf("%d", r.Evidence.DurationMs)
				at = r.Evidence.ObservedAt
			}
			fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %s | %s | %s |\n", r.ID, r.Status, r.Mode, mdEscape(r.Reason), exit, sha, ms, at)
		}
		b.WriteString("\n")
	}
	return b.String()
}

func mdEscape(s string) string {
	s = strings.ReplaceAll(s, "|", "\\|")
	return strings.ReplaceAll(s, "\n", " ")
}

// FindMatrixFile searches upward from start for DefaultMatrixPath.
func FindMatrixFile(start string) (string, bool) {
	dir := start
	for {
		candidate := filepath.Join(dir, DefaultMatrixPath)
		if _, err := os.Stat(candidate); err == nil {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// DispatchVerdict is the conformance gate outcome for one provider.
type DispatchVerdict struct {
	Provider       string    `json:"provider"`
	Known          bool      `json:"known"`
	Refuse         bool      `json:"refuse"`
	FailedRequired []ProbeID `json:"failed_required,omitempty"`
	Message        string    `json:"message,omitempty"`
}

// CheckDispatch evaluates whether dispatch to provider should be refused.
// Only required-probe FAIL verdicts refuse; UNVERIFIED never blocks.
func (m *Matrix) CheckDispatch(providerName string) DispatchVerdict {
	v := DispatchVerdict{Provider: providerName}
	rep, ok := m.Find(providerName)
	if !ok {
		return v
	}
	v.Known = true
	v.FailedRequired = rep.FailedRequired()
	if len(v.FailedRequired) > 0 {
		v.Refuse = true
		ids := make([]string, len(v.FailedRequired))
		for i, id := range v.FailedRequired {
			ids[i] = string(id)
		}
		v.Message = fmt.Sprintf("E_PROVIDER_CONFORMANCE_FAIL: provider %q failed required conformance probes [%s] (observed %s); see %s",
			rep.Name, strings.Join(ids, ","), m.GeneratedAt, DefaultMatrixPath)
	}
	return v
}

// CheckDispatchFromDir loads the matrix found upward from dir (if any) and
// evaluates the dispatch gate. A missing matrix yields a non-refusing verdict.
func CheckDispatchFromDir(dir, providerName string) (DispatchVerdict, error) {
	path, ok := FindMatrixFile(dir)
	if !ok || strings.TrimSpace(providerName) == "" {
		return DispatchVerdict{Provider: providerName}, nil
	}
	m, err := LoadMatrix(path)
	if err != nil {
		return DispatchVerdict{Provider: providerName}, err
	}
	return m.CheckDispatch(providerName), nil
}
